import * as E from './engine.js?v=0.5.0';
import * as C from './camp.js?v=0.5.0';
import * as UI from './camp-ui.js?v=0.5.0';
import * as O from './objectives.js?v=0.5.0';

export const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const money=n=>'₺'+Math.round(n).toLocaleString('tr-TR');
export const button=(text,action,value='',kind='',disabled=false)=>`<button class="${kind}" data-action="${action}" data-value="${esc(value)}" ${disabled?'disabled':''}>${text}</button>`;
export const section=(title,note='')=>`<div class="section-head"><h2>${title}</h2><span>${note}</span></div>`;
const short={boxing:'Boks',kickboxing:'Kickboks',wrestling:'Güreş',bjj:'BJJ',stamina:'Kondisyon',strength:'Kuvvet'};
const discipline={boxing:'01',kickboxing:'02',wrestling:'03',bjj:'04',stamina:'05',rope:'06',strength:'07'};
const trainingList=[['boxing','Boks','Yumruk, isabet ve gard.'],['kickboxing','Kickboks','Tekme, mesafe ve ayak oyunu.'],['wrestling','Güreş','Yere al, pozisyon kazan.'],['bjj','Brazilian Jiu-Jitsu','Kontrol, kaçış ve pes ettirme.'],['stamina','Koşu','Nefesini daha uzun koru.'],['rope','İp atlama','Ritim ve dayanıklılık.'],['strength','Kuvvet','Darbe gücü ve kas gelişimi.']];
export function tabs(items,selected,action){return `<div class="segmented" aria-label="Bölüm seçimi">${items.map(([id,label])=>`<button class="${selected===id?'active':''}" data-action="${action}" data-value="${id}" aria-pressed="${selected===id}">${label}</button>`).join('')}</div>`;}
export function nextStep(s){
 if(s.health<50)return {label:'ÖNCE TOPARLAN',title:'Vücuduna zaman ver.',text:'Sağlığın düşük. Uyku ve dinlenme seni yeniden maça hazırlar.',action:'recovery',button:'Toparlan'};
 if(s.food<30)return {label:'YAKITIN AZALIYOR',title:'Bir öğünle devam et.',text:'Düşük tokluk antrenmanı ve maç hazırlığını zorlaştırır.',action:'recovery',button:'Yemek seçenekleri'};
 if(s.energy<30||s.sleep<30||s.fatigue>=60)return {label:'TOPARLANMA ZAMANI',title:'Dinlenmek de programın parçası.',text:`Antrenman yükün ${Math.round(s.fatigue)}/100. Uyku ve dinlenmeyle yeniden verim kazan.`,action:'recovery',button:'Mola ver'};
 if(s.camp&&C.remaining(s)===0)return {label:'BU GECE SENİN GECEN',title:`${s.camp.enemy.name} seni bekliyor.`,text:'Hazırlık bitti. Teknik setini kontrol et ve kafese çık.',action:'nav',value:'fight',button:'Maç gününe git'};
 if(s.camp){const focus=C.scouting(s,s.camp.enemy).focus;return {label:UI.timeLeft(s).toLocaleUpperCase('tr-TR'),title:'Planlı çalış. Dinç çık.',text:`${s.camp.enemy.name} için köşe önerisi: ${C.FOCUSES[focus].name.toLocaleLowerCase('tr-TR')}.`,action:'nav',value:'train',button:'Kamp antrenmanı'};}
 if(s.sessions<3)return {label:'İLK ADIMIN',title:'Dövüş kimliğini inşa et.',text:'Güçlü olmak istediğin dalı seç. Kondisyon ve toparlanmaya da yer ayır.',action:'nav',value:'train',button:'Antrenmana başla'};
 return {label:'SIRADAKİ HEDEF',title:'İsmini sıralamaya yazdır.',text:'Rakibini seç, yedi günlük kampını planla. Her yeni rakip ayrı bir sınav.',action:'nav',value:'fight',button:'Rakip seç'};
}
export function nextCard(s){const n=nextStep(s);return `<article class="next-card"><div><span class="eyebrow">${esc(n.label)}</span><h2>${esc(n.title)}</h2><p>${esc(n.text)}</p></div>${button(n.button,n.action,n.value||'','primary')}</article>`;}
export function homeContext(s){const p=E.leagueProgress(s);return `<span class="eyebrow">DÖVÜŞÇÜ PROFİLİ</span><div class="profile-record"><strong>${s.wins}<i>–</i>${s.losses}</strong><span>GALİBİYET / MAĞLUBİYET</span></div><div class="profile-pills"><span>${UI.fightingStyle(s)}</span><span>${s.sessions} seans</span><span>${s.world.reputation} itibar</span></div><div class="profile-progress"><div class="row"><span>${E.LEAGUES[p.current].name}</span><b>${p.current===3?s.leagueWins[3]+'/7':p.earned+'/'+p.required}</b></div><div class="bar"><i style="width:${Math.min(100,(p.current===3?s.leagueWins[3]/7:p.earned/p.required)*100)}%"></i></div><p>${p.next===null?'Kemer için 7 farklı rakibi yen ve 1. sıraya yüksel.':`${E.LEAGUES[p.next].name} için ${p.remaining} farklı rakibe karşı ilk zafer.`}</p></div>${button('Dövüşçü detayları','profile','','ghost')}`;}
export function homeContent(s){const goal=O.list(s).find(g=>!g.claimed);return `<div class="quick-actions">${button('Yemek & uyku','recovery','','')}${button('Antrenman','nav','train')}${button('Gündelik iş','job-sheet')}${button('Hedefler','goals')}</div>${nextCard(s)}${goal?section('Bir sonraki kilometre taşı','KARİYER HEDEFİ')+goalCard(goal,true):''}${section('Bugünün özeti',E.day(s)+'. GÜN')}<div class="summary-grid"><article><span>ANTRENMAN YÜKÜ</span><strong>${Math.round(s.fatigue)}<small>/100</small></strong><p>${UI.fatigueLabel(s)}</p></article><article><span>YAŞAM ALANIN</span><strong class="text-metric">${['Paylaşımlı oda','Kendi dairen','Sporcu evi'][s.world.home]}</strong><p>${s.world.sponsor?'Sponsor desteğin aktif.':'Şehirde yeni bağlantılar kur.'}</p></article></div>`;}
export function training(s,tab='sessions',filter='technique'){
 const controls=tabs([['sessions','Çalışmalar'],['moves','Teknik seti'],['gym','Salon & ekip']],tab,'train-tab');
 if(tab==='moves')return {tools:controls,content:UI.loadout(s)};
 if(tab==='gym')return {tools:controls,content:gyms(s)};
 const blocked=s.fatigue>=85||!!s.camp&&C.remaining(s)===0;
 const data=trainingList.filter(([key])=>filter==='technique'?['boxing','kickboxing','wrestling','bjj'].includes(key):filter==='conditioning'?['stamina','rope','strength'].includes(key):false);
 const content=`<div class="training-context"><div><strong>${E.GYMS[s.gym].name}</strong><span>${s.coach?E.COACHES[s.coach].name:'Kendi programın'} · Yük ${Math.round(s.fatigue)}</span></div>${button('Toparlan','recovery','','ghost')}</div>${tabs([['technique','Dövüş'],['conditioning','Fizik'],['camp','Kamp odağı']],filter,'train-filter')}${filter==='camp'?(s.camp?UI.prepCards(s):`<div class="empty"><strong>Rakibe özel bir plan.</strong><p>Maç ayarlayınca savunma, mesafe ve yerden kaçış çalışmaların burada açılır.</p>${button('Rakip seç','nav','fight','primary')}</div>`):`<div class="training-list">${data.map(([key,name,desc])=>{const skill=key==='rope'?'stamina':key,p=E.trainingPreview(s,key);return `<article class="training-card"><div class="training-symbol ${skill}">${discipline[key]}</div><div class="training-main"><div class="row"><h2>${name}</h2><span class="level-pill">${Math.floor(s.skills[skill])}<small> / 100</small></span></div><p>${desc}</p><div class="training-yield"><strong>+${p.gain.toFixed(2)} ${short[skill]}</strong><span>${money(p.cost)} · 1 sa</span></div><div class="training-resource">−18 enerji · −11 tokluk · −9 dinçlik · +${p.fatigue} yük</div><div class="training-actions">${button('Ritimle çalış','active-train',key,'primary',blocked||s.skills[skill]>=100)}${button('Hızlı çalış','train',key,'ghost',blocked||s.skills[skill]>=100)}</div></div></article>`;}).join('')}</div><p class="help-text training-note">Ritim çalışması en fazla %25 ek gelişim sağlar. Aynı gün tekrarlar ve biriken yük gelişimi azaltır.</p>`}${blocked?`<div class="notice">${s.camp&&C.remaining(s)===0?'Maç günün geldi. Toparlanıp kafese çık veya kampı iptal et.':'Yükün çok yüksek. Yeni bir seans için önce dinlen.'}</div>`:''}`;
 return {tools:controls,content};
}
function gyms(s){return `<div class="section-intro">Üyelik ve antrenör anlaşması bir kez ödenir; ilgili çalışmaların seans bedeli ayrıca gösterilir. Koşu ve ip atlama ücretsizdir.</div>${section('Antrenman alanın','4 SALON')}<div class="cards">${E.GYMS.map((g,i)=>`<article class="card gym-card ${s.gym===i?'equipped':''}"><span class="gym-art gym-art-${i}"><b>0${i+1}</b><i>${['EV','SOKAK','DISTRICT','APEX'][i]}</i></span><span class="tag">${s.gym===i?'MEVCUT SALON':s.ownedGyms.includes(i)?'ÜYELİĞİN VAR':'YENİ BİR BASAMAK'}</span><h3>${g.name}</h3><p>${g.sub}</p><div class="card-facts"><span>Gelişim <b>×${g.gain.toFixed(1)}</b></span><span>Seans <b>${money(g.fee)}</b></span></div><span class="cost">${s.ownedGyms.includes(i)?'Geçiş ücretsiz':`Üyelik ${money(g.price)}`}${g.wins?' · '+g.wins+' galibiyet':''}</span>${button(s.gym===i?'Burada çalışıyorsun':s.ownedGyms.includes(i)?'Salona geç':'Üyelik al','gym',i,'',s.gym===i||s.wins<g.wins)}</article>`).join('')}</div>${section('Köşendeki uzman','1 AKTİF ANTRENÖR')}<div class="cards">${E.COACHES.slice(1).map((c,j)=>{const i=j+1;return `<article class="card ${s.coach===i?'equipped':''}"><div class="coach-avatar">${['CS','DH','BD','EY'][j]}</div><span class="tag">${short[c.skill]} · +%${Math.round(c.bonus*100)} gelişim</span><h3>${c.name}</h3><p>Yalnız uzmanlık dalındaki seanslarda ücret alır.</p><span class="cost">Anlaşma ${money(c.price)} · Seans ${money(c.fee)}</span>${button(s.coach===i?'Köşende':s.ownedCoaches.includes(i)?'Birlikte çalış':'Anlaşma yap','coach',i,'',s.coach===i)}</article>`;}).join('')}</div>${s.coach?`<div class="inline-actions">${button('Antrenörsüz çalış','coach',0,'ghost')}</div>`:''}`;}
export function fightLobby(s,tier=E.league(s),tab='camp'){
 if(s.camp){return {tools:tabs([['camp','Kamp'],['scout','Rakip'],['moves','Teknikler']],tab,'fight-tab'),content:tab==='scout'?UI.scouting(s,s.camp.enemy):tab==='moves'?UI.loadout(s):`<div class="camp-dashboard"><div class="camp-overview">${UI.campOverview(s)}</div><div class="camp-advice"><span class="eyebrow">KÖŞENİN PLANI</span><h3>${C.FOCUSES[C.scouting(s,s.camp.enemy).focus].name}</h3><p>${C.scouting(s,s.camp.enemy).recommendation}</p>${button('Kamp odağını çalış','camp-train','','primary',C.remaining(s)===0)}${button('Rakip dosyasını aç','fight-tab','scout','ghost')}</div></div>`};}
 const offers=E.matchOffers(s,tier),summary=E.competitionSummary(s,tier);
 return {tools:tabs(E.LEAGUES.slice(0,E.league(s)+1).map((x,i)=>[String(i),x.name]),String(tier),'fight-tier'),content:`<div class="lobby-intro"><div><span class="eyebrow">${E.LEAGUES[tier].name.toLocaleUpperCase('tr-TR')}</span><h2>Sıradaki rakibin kim?</h2><p>7 oyun günü hazırlan. ${tier<E.league(s)?'Alt lig maçları gelir ve deneyim sağlar; üst lig ilerlemeni artırmaz.':tier===3?'Kemer için yedi farklı rakibi yen ve ilk sıraya yüksel.':'Farklı rakiplere karşı ilk zaferlerin seni üst lige taşır.'}</p></div><span class="rank-disc"><b>#${summary.rank}</b><small>SIRALAMAN</small></span></div><div class="offer-list">${offers.map((o,i)=>`<article class="opponent-card ${i===0?'recommended':''}"><div class="opponent-art style-${o.style}"><span>#${o.rank}</span><b>${o.name.split(' ').map(x=>x.match(/\p{L}/u)?.[0]||'').slice(0,2).join('')}</b><i>${short[o.style]}</i></div><div class="opponent-info"><span class="eyebrow">${esc(o.reason)}</span><h2>${esc(o.name)}</h2><div class="opponent-stats"><span>${short[o.style]}</span><span>Aranızda ${o.record.wins}G · ${o.record.losses}M</span></div><p>${tier<E.league(s)?'Alt lig: para ve maç deneyimi kazan.':o.qualifies?'İlk zafer: '+(tier===3?'kemer':'lig')+' ilerlemesi kazan.':'Rövanş: para ve maç deneyimi kazan.'}</p><div class="offer-purse"><strong>${money(E.LEAGUES[tier].purse)}</strong><span>Zafer ödülü</span></div><div class="buttons">${button('Rakibi incele','scout-offer',o.id,'ghost')}${button('Kampı başlat','book',tier+':'+o.id,'primary')}</div></div></article>`).join('')}</div>`};
}
export function goalCard(g,compact=false){return `<article class="goal-card ${g.claimed?'claimed':g.complete?'ready':''}"><div class="goal-mark">${g.claimed?'✓':g.complete?'!':String(g.current).padStart(2,'0')}</div><div class="goal-body"><span class="eyebrow">${esc(g.chapterTitle||'KARİYER HEDEFİ')}</span><h3>${esc(g.title)}</h3>${compact?'':`<p>${esc(g.description)}</p>`}<div class="goal-progress"><div class="bar"><i style="width:${Math.min(100,g.current/g.target*100)}%"></i></div><span>${Math.min(g.current,g.target)}/${g.target}</span></div><span class="cost">${g.rewardCash?money(g.rewardCash):''}${g.rewardRep?' · +'+g.rewardRep+' itibar':''}</span></div>${button(g.claimed?'Alındı':g.complete?'Ödülü al':'Sürüyor','claim',g.id,g.complete&&!g.claimed?'primary':'ghost',!g.complete||g.claimed)}</article>`;}
export function career(s,tab='ladder'){
 const summary=E.competitionSummary(s),l=summary.tier;
 const tools=tabs([['ladder','Sıralama'],['goals','Hedefler'],['history','Geçmiş']],tab,'career-tab');
 let content=`<div class="career-banner"><div><span class="eyebrow">${E.LEAGUES[l].name.toLocaleUpperCase('tr-TR')}</span><h2>${summary.champion?'Kemer senin.':'Adım adım zirveye.'}</h2><p>${l===3?'Kemer yolu: '+s.leagueWins[3]+'/7 farklı rakip ve 1. sıra':`Üst lige ${summary.promotion.remaining} farklı rakip galibiyeti.`}</p></div><strong>#${summary.rank}</strong></div>`;
 if(tab==='goals')return {tools,content:content+`<div class="objectives-list">${O.list(s).map(g=>goalCard(g)).join('')}</div>`};
 if(tab==='history')return {tools,content:content+`<div class="career-totals"><span><b>${s.wins}–${s.losses}</b>Maç karnesi</span><span><b>${money(s.earned)}</b>Toplam kazanç</span><span><b>${s.sessions}</b>Antrenman</span></div>`+(s.history.length?`<div class="history-list">${s.history.map(h=>`<article class="history-row"><span class="history-result ${h.won?'win':h.draw?'draw':'loss'}">${h.won?'G':h.draw?'B':'M'}</span><div><h3>${esc(h.name)}</h3><p>${h.day}. gün · ${E.LEAGUES[h.tier].name} · ${esc(h.method)}</p></div><strong>${money(h.reward)}</strong></article>`).join('')}</div>`:'<div class="empty"><strong>İlk maçını hatırlayacaksın.</strong><p>Rakip seçip hazırlık kampını başlat.</p>'+button('Maç teklifleri','nav','fight','primary')+'</div>')};
 return {tools,content:content+`<div class="ladder-list">${summary.ladder.map(row=>`<article class="ladder-row ${row.player?'you':''}"><strong class="ladder-rank">${row.rank===1?'♛':'#'+row.rank}</strong><div><h3>${esc(row.name)}${row.player?'<small>SEN</small>':''}</h3><p>${short[row.style]||'MMA'}${!row.player&&row.record?` · Aranızda ${row.record.wins}G / ${row.record.losses}M`:''}</p></div><span>${row.player?`${s.wins}–${s.losses}`:row.record?.wins?'✓':''}</span></article>`).join('')}</div><p class="help-text">Senden yukarıdaki rakibi yenince sıralamada yer değiştirirsiniz. Aynı rakibe tekrar kazanmak lig ve kemer ilerlemesi kazandırmaz.</p>${summary.rivals.length?section('Yollarınız yine kesişecek','REKABET')+`<div class="cards">${summary.rivals.slice(0,3).map(r=>`<article class="card rival-card"><span class="eyebrow">${r.meetings} KARŞILAŞMA</span><h3>${esc(r.name)}</h3><p>Aranızda ${r.record.wins} galibiyet, ${r.record.losses} mağlubiyet.</p><span class="tag">Son karşılaşma · ${r.lastDay}. gün</span></article>`).join('')}</div>`:''}`};
}
